#!/usr/bin/env python3
"""
VesselFramework Single-File Runtime + Evil Twin
=================================================

A portable single-file launcher that embeds the uploaded VesselFramework artifacts.

"Evil Twin" here means a DEFENSIVE ADVERSARIAL ANALYST:
it is a separate challenge pass designed to attack the primary analysis for weak
evidence, hidden assumptions, mechanism/placement mistakes, overclaiming,
alternative explanations, and untested dependencies.

It is NOT a rogue-Wi-Fi / credential-capture implementation.

Modes
-----
selftest
list
extract
show
case
forecast
agent
twin
duel
recognition

The embedded package can be materialized into a temporary directory when one of
the legacy runners expects neighboring files. The user still edits/runs one .py file.
"""

from __future__ import annotations

import argparse
import base64
import gzip
import hashlib
import json
import os
import re
import subprocess
import sys
import tempfile
from pathlib import Path
from typing import Any
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen

SINGLE_FILE_VERSION = "0.2"
BUNDLE_SHA256 = "d576f04b805bf10b9c09573358b7c24458a3216fb53270ebe24cde9fa01d2085"
_BUNDLE_B64 = """"""

PRIMARY_SYSTEM = r"""
You are the primary VesselFramework analyst.
Use evidence-calibrated reasoning. Distinguish source-established facts,
analysis, hypotheses, and illustrations. Do not invent evidence or provenance.
For cybersecurity control questions, reason through asset, threat, attack path,
trust boundary, control point, mechanism, dependencies, failure mode, residual
path, and evidence. Return a concise decision-grade analysis.
"""

TWIN_SYSTEM = r"""
You are EVIL TWIN, a defensive adversarial-analysis challenger.

Your job is not to agree with the primary analyst. Try to break the analysis.

Challenge it using:
1. CLAIM BOUNDARY — what is asserted beyond the evidence?
2. PROVENANCE — what evidence may be derivative, unresolved, stale, or circular?
3. MECHANISM — is the named security mechanism actually the one described?
4. PLACEMENT — does the control act where the attack must pass or succeed?
5. QUALIFIER — did words such as inline, passive, mutual, remote, internal,
   compensating, corrective, fail-open, fail-closed, etc. change the answer?
6. DEPENDENCY — what required identity, telemetry, policy, endpoint, network,
   administrator, vendor, or availability dependency is hidden?
7. RESIDUAL PATH — if the proposed control works perfectly, what permitted path remains?
8. ALTERNATIVE — what is the strongest plausible competing explanation or answer?
9. FAILURE MODE — how can the control or reasoning fail?
10. DISCONFIRMER — what observation would show the primary analysis is wrong?

In external deliverables, use the target domain's terminology; cite framework labels with attribution.
Do not manufacture attacks, evidence, credentials, or facts. This is a critique layer.
Return: challenges, severity, what survives challenge, and what must be tested.
"""

ARBITER_SYSTEM = r"""
You are the adjudicator between a primary cybersecurity analysis and an
adversarial Evil Twin critique. Preserve claims that survive challenge, downgrade
claims that do not, identify the exact remaining uncertainty, and give the next
test or decision rule. Do not average the two analyses mechanically.
"""

EMBEDDED_EVIL_TWIN_SKILL = r"""---
name: vessel-framework-evil-twin-adversarial-analyst
description: Challenges primary analyses for unsupported claims, provenance weakness,
    mechanism or placement errors, hidden dependencies, residual paths, and missing tests.
---

# VesselFramework Evil Twin Adversarial Analyst
## Version 0.1 - Research Candidate

Use this defensive challenge layer before release or action. Attack the primary
analysis for claim overreach, unresolved provenance, mechanism or placement
errors, hidden dependencies, residual paths, missing alternatives, and absent
disconfirming tests. Do not perform unauthorized access, credential capture,
exploitation, wireless impersonation, or remote action.

The required result identifies the claim under review, evidence limitation,
challenge category, severity, surviving or downgraded claims, residual path,
strongest alternative, next discriminating test, and PASS, REVISE, or BLOCK
recommendation. Repeated or derivative sources do not establish independence.
"""


def _load_bundle() -> dict[str, str]:
    raw = gzip.decompress(base64.b64decode(_BUNDLE_B64.encode("ascii")))
    if hashlib.sha256(raw).hexdigest() != BUNDLE_SHA256:
        raise RuntimeError("Embedded bundle integrity check failed.")
    value = json.loads(raw.decode("utf-8"))
    if not isinstance(value, dict):
        raise TypeError("Embedded bundle is invalid.")
    bundle = {str(k): str(v) for k, v in value.items()}
    bundle["VesselFramework_Evil_Twin_Adversarial_Analyst_SKILL_v0.1.md"] = (
        EMBEDDED_EVIL_TWIN_SKILL
    )
    return bundle


def list_resources() -> list[str]:
    return sorted(_load_bundle())


def materialize(target: Path) -> Path:
    target.mkdir(parents=True, exist_ok=True)
    for name, text in _load_bundle().items():
        out = target / name
        out.write_text(text, encoding="utf-8")
    return target


def show_resource(name: str) -> None:
    bundle = _load_bundle()
    if name not in bundle:
        raise KeyError(f"Unknown embedded resource: {name}")
    print(bundle[name])


def _python() -> str:
    return sys.executable


def run_legacy(script_name: str, passthrough: list[str]) -> int:
    with tempfile.TemporaryDirectory(prefix="vesselframework_onefile_") as tmp:
        root = materialize(Path(tmp))
        script = root / script_name
        if not script.is_file():
            raise FileNotFoundError(f"Embedded runner not found: {script_name}")
        proc = subprocess.run([_python(), str(script), *passthrough], cwd=root, check=False)
        return int(proc.returncode)


def _api_config() -> tuple[str, str, str]:
    key = os.environ.get("VESSELFRAMEWORK_API_KEY") or os.environ.get("OPENAI_API_KEY")
    if not key:
        raise RuntimeError(
            "No API key found. Set VESSELFRAMEWORK_API_KEY or OPENAI_API_KEY, "
            "or use `twin --offline`."
        )
    base = os.environ.get("VESSELFRAMEWORK_BASE_URL", "https://api.openai.com/v1").rstrip("/")
    model = os.environ.get("VESSELFRAMEWORK_MODEL", "gpt-4o-mini")
    return key, base, model


def chat(system: str, user: str, *, model_override: str | None = None) -> str:
    key, base, model = _api_config()
    model = model_override or model
    body = json.dumps(
        {
            "model": model,
            "messages": [
                {"role": "system", "content": system},
                {"role": "user", "content": user},
            ],
            "temperature": 0.2,
        }
    ).encode("utf-8")
    req = Request(
        f"{base}/chat/completions",
        data=body,
        method="POST",
        headers={
            "Authorization": f"Bearer {key}",
            "Content-Type": "application/json",
        },
    )
    try:
        with urlopen(req, timeout=120) as resp:
            data = json.loads(resp.read().decode("utf-8"))
    except HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"API HTTP {exc.code}: {detail[:1000]}") from exc
    except URLError as exc:
        raise RuntimeError(f"API connection failed: {exc}") from exc
    return str(data["choices"][0]["message"]["content"])


def offline_twin(draft: str) -> str:
    """
    Deterministic local challenge pass.
    It does not claim semantic equivalence to an LLM adversarial review.
    """
    findings: list[str] = []
    low = draft.lower()

    absolute_terms = [
        "always", "never", "proves", "guarantees", "completely", "eliminates",
        "must be", "certainly", "definitely",
    ]
    hits = [term for term in absolute_terms if term in low]
    if hits:
        findings.append(
            "CLAIM BOUNDARY: absolute language detected: " + ", ".join(sorted(set(hits)))
        )

    if not re.search(r"\b(evidence|source|citation|telemetry|log|test|observed)\b", low):
        findings.append(
            "EVIDENCE: no obvious evidence/test language detected; conclusions may exceed support."
        )

    if re.search(r"\b(ids|span|mirror|tap|passive)\b", low) and re.search(
        r"\b(block|prevent|drop|stop automatically)\b", low
    ):
        findings.append(
            "PLACEMENT/MECHANISM: passive monitoring language is mixed with direct blocking; verify inline enforcement."
        )

    if "vpn" in low and re.search(r"\btrust|trusted|safe|secure user\b", low):
        findings.append(
            "DEPENDENCY: VPN confidentiality/authentication does not by itself establish authorization or endpoint trust."
        )

    if "firewall" in low and "lateral" in low and "segmentation" not in low:
        findings.append(
            "PLACEMENT: lateral-movement risk may require internal segmentation rather than only perimeter filtering."
        )

    if "compensating" in low and "restore" in low:
        findings.append(
            "DEFINITION: compensating and corrective control functions may be conflated."
        )

    if not re.search(r"\b(alternative|however|unless|residual|bypass|disconfirm)\b", low):
        findings.append(
            "ALTERNATIVE/RESIDUAL PATH: no explicit competing explanation or bypass path found."
        )

    if not findings:
        findings.append(
            "No simple deterministic defect signature found. Run API-backed twin mode for a semantic adversarial review."
        )

    return "\n".join(f"- {item}" for item in findings)



RECOGNITION_CLASSES = (
    "SELF-CONTROLLED",
    "PLATFORM-INDEXED",
    "INSTITUTIONAL",
    "INDEPENDENT-MENTION",
    "INDEPENDENT-EVALUATION",
    "INDEPENDENT-ADOPTION",
    "UNRESOLVED",
)

RECOGNITION_WEIGHTS = {
    "SELF-CONTROLLED": 0,
    "PLATFORM-INDEXED": 1,
    "INSTITUTIONAL": 2,
    "INDEPENDENT-MENTION": 3,
    "INDEPENDENT-EVALUATION": 4,
    "INDEPENDENT-ADOPTION": 5,
    "UNRESOLVED": 0,
}


def normalize_identity(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", " ", value.lower()).strip()


def classify_recognition_item(item: dict[str, Any]) -> dict[str, Any]:
    """
    Deterministic first-pass classification.
    The caller may explicitly provide `class`; otherwise conservative heuristics apply.
    """
    out = dict(item)
    explicit = str(out.get("class", "")).upper().strip()
    if explicit in RECOGNITION_CLASSES:
        classification = explicit
    else:
        source_type = normalize_identity(str(out.get("source_type", "")))
        relation = normalize_identity(str(out.get("relation", "")))
        text = normalize_identity(
            " ".join(
                str(out.get(k, ""))
                for k in ("title", "description", "source", "source_type", "relation")
            )
        )
        if any(x in source_type for x in ("self controlled", "personal", "author upload")):
            classification = "SELF-CONTROLLED"
        elif any(x in source_type for x in ("platform indexed", "index", "aggregator")):
            classification = "PLATFORM-INDEXED"
        elif any(x in source_type for x in ("institutional", "university", "government", "official record")):
            classification = "INSTITUTIONAL"
        elif any(x in relation for x in ("adoption", "implemented", "used by", "adopted")):
            classification = "INDEPENDENT-ADOPTION"
        elif any(x in relation for x in ("evaluation", "review", "citation", "cited", "peer review")):
            classification = "INDEPENDENT-EVALUATION"
        elif any(x in relation for x in ("mention", "discussion", "conference", "interview")):
            classification = "INDEPENDENT-MENTION"
        elif "researchgate" in text and "uploaded by" in text:
            classification = "SELF-CONTROLLED"
        else:
            classification = "UNRESOLVED"

    out["class"] = classification
    out["weight"] = RECOGNITION_WEIGHTS[classification]
    return out


def recognition_gate(subject: str, items: list[dict[str, Any]]) -> dict[str, Any]:
    """
    Identity & Recognition Provenance Gate.

    Critical rule:
      evidence count != independent validation count.

    Independence is deduplicated by `root_id` when supplied. If root lineage is
    missing, the item can be displayed but cannot silently create an independent root.
    """
    if not isinstance(subject, str) or not subject.strip():
        raise ValueError("Recognition subject must be a non-empty string.")
    if not isinstance(items, list) or not all(isinstance(item, dict) for item in items):
        raise ValueError("Recognition evidence must be a list of JSON objects.")

    classified = [classify_recognition_item(x) for x in items]

    identity_matches = []
    quarantined = []
    subject_norm = normalize_identity(subject)

    for item in classified:
        claimed = normalize_identity(str(item.get("identity", "")))
        identity_status = str(item.get("identity_status", "")).upper().strip()

        attrs = item.get("corroborating_attributes") or []
        has_corroboration = isinstance(attrs, list) and len(attrs) >= 2

        if identity_status == "MATCH" and has_corroboration:
            identity_matches.append(item)
        elif identity_status == "MATCH":
            item["identity_status"] = "UNRESOLVED-NAME-ONLY"
            quarantined.append(item)
        elif identity_status in {"MISMATCH", "QUARANTINE"}:
            quarantined.append(item)
        elif claimed and (claimed == subject_norm or claimed in subject_norm or subject_norm in claimed):
            # Name-only matches remain unresolved unless corroborating attributes are supplied.
            if has_corroboration:
                item["identity_status"] = "MATCH"
                identity_matches.append(item)
            else:
                item["identity_status"] = "UNRESOLVED-NAME-ONLY"
                quarantined.append(item)
        else:
            item["identity_status"] = "UNRESOLVED"
            quarantined.append(item)

    roots: dict[str, dict[str, Any]] = {}
    unresolved_lineage = []
    for item in identity_matches:
        root = str(item.get("root_id", "")).strip()
        if not root:
            unresolved_lineage.append(item)
            continue
        existing = roots.get(root)
        if existing is None or item["weight"] > existing["weight"]:
            roots[root] = item

    independent = list(roots.values())
    strongest_weight = max((x["weight"] for x in independent), default=0)
    strongest_class = next(
        (k for k, v in RECOGNITION_WEIGHTS.items() if v == strongest_weight),
        "UNRESOLVED",
    )

    independent_eval = sum(
        1 for x in independent
        if x["class"] in {"INDEPENDENT-EVALUATION", "INDEPENDENT-ADOPTION"}
    )

    if any(x["class"] == "INDEPENDENT-ADOPTION" for x in independent):
        stage = "INDEPENDENT-ADOPTION"
    elif independent_eval:
        stage = "INDEPENDENT-EVALUATION"
    elif any(x["class"] == "INDEPENDENT-MENTION" for x in independent):
        stage = "INDEPENDENT-MENTION"
    elif any(x["class"] == "INSTITUTIONAL" for x in independent):
        stage = "INSTITUTIONAL-VALIDATION"
    elif any(x["class"] == "PLATFORM-INDEXED" for x in independent):
        stage = "PLATFORM-DISCOVERY"
    elif any(x["class"] == "SELF-CONTROLLED" for x in identity_matches):
        stage = "SELF-PUBLISHED-PRESENCE"
    else:
        stage = "NOT-ESTABLISHED"

    return {
        "subject": subject,
        "stage": stage,
        "strongest_class": strongest_class,
        "raw_item_count": len(items),
        "identity_match_count": len(identity_matches),
        "independent_root_count": len(independent),
        "independent_evaluation_or_adoption_roots": independent_eval,
        "unresolved_lineage_count": len(unresolved_lineage),
        "quarantined_identity_count": len(quarantined),
        "independent_roots": independent,
        "unresolved_lineage": unresolved_lineage,
        "quarantined": quarantined,
        "rule": "Repeated/self-controlled/derivative results do not become independent validation merely by quantity.",
    }


def recognition_report(result: dict[str, Any]) -> str:
    lines = [
        "=== IDENTITY & RECOGNITION PROVENANCE GATE ===",
        f"Subject: {result['subject']}",
        f"Stage: {result['stage']}",
        f"Strongest class: {result['strongest_class']}",
        f"Raw evidence items: {result['raw_item_count']}",
        f"Identity matches: {result['identity_match_count']}",
        f"Independent provenance roots: {result['independent_root_count']}",
        f"Independent evaluation/adoption roots: {result['independent_evaluation_or_adoption_roots']}",
        f"Unresolved lineage: {result['unresolved_lineage_count']}",
        f"Quarantined identity items: {result['quarantined_identity_count']}",
        "",
        "Independent roots:",
    ]
    if result["independent_roots"]:
        for item in result["independent_roots"]:
            lines.append(
                f"- [{item['class']}] {item.get('title') or item.get('description') or item.get('source') or 'Untitled'} "
                f"(root={item.get('root_id')})"
            )
    else:
        lines.append("- None established.")

    if result["quarantined"]:
        lines.extend(["", "Quarantined / unresolved identity items:"])
        for item in result["quarantined"]:
            lines.append(
                f"- [{item.get('identity_status','UNRESOLVED')}] "
                f"{item.get('title') or item.get('description') or item.get('source') or 'Untitled'}"
            )

    lines.extend(["", "Decision rule:", result["rule"]])
    return "\n".join(lines)



def build_twin_input(question: str, draft: str, evidence: str = "") -> str:
    return f"""QUESTION
{question}

PRIMARY ANALYSIS
{draft}

EVIDENCE / CONTEXT
{evidence if evidence else "[No additional evidence supplied]"}

Attack the primary analysis. Do not merely rewrite it.
"""


def run_twin(question: str, draft: str, evidence: str, offline: bool) -> str:
    if offline:
        return offline_twin(draft)
    twin_model = os.environ.get("VESSELFRAMEWORK_TWIN_MODEL")
    return chat(TWIN_SYSTEM, build_twin_input(question, draft, evidence), model_override=twin_model)


def run_duel(question: str, evidence: str = "") -> tuple[str, str, str]:
    primary = chat(
        PRIMARY_SYSTEM,
        f"QUESTION:\n{question}\n\nEVIDENCE / CONTEXT:\n{evidence or '[None supplied]'}",
    )
    twin = run_twin(question, primary, evidence, offline=False)
    arbiter = chat(
        ARBITER_SYSTEM,
        f"""QUESTION
{question}

PRIMARY
{primary}

EVIL TWIN CHALLENGE
{twin}

EVIDENCE / CONTEXT
{evidence or "[None supplied]"}

Adjudicate. State what survives, what is downgraded, and the next discriminating test.
""",
    )
    return primary, twin, arbiter


def selftest() -> int:
    bundle = _load_bundle()
    required = {
        "SKILL.md",
        "VesselFramework_MetaMatrix_Framework_v3.8_v3.9_Combined.md",
        "vesselframework_reference_v1.1_provenance_firewall.py",
        "vesselframework_case_runner.py",
        "vesselframework_agent.py",
    }
    missing = sorted(required - set(bundle))
    if missing:
        print("SELFTEST: FAIL")
        print("Missing:", ", ".join(missing))
        return 1

    compile_failures: list[str] = []
    for name, text in bundle.items():
        if name.endswith(".py"):
            try:
                compile(text, name, "exec")
            except SyntaxError as exc:
                compile_failures.append(f"{name}: {exc}")

    if compile_failures:
        print("SELFTEST: FAIL")
        for failure in compile_failures:
            print(failure)
        return 1

    print("SELFTEST: PASS")
    print(f"Single-file version: {SINGLE_FILE_VERSION}")
    print(f"Embedded resources: {len(bundle)}")
    print(f"Bundle SHA-256: {BUNDLE_SHA256}")
    print("Evil Twin mode: defensive adversarial analysis")
    return 0


def _read_arg_or_file(value: str | None) -> str:
    if not value:
        return ""
    p = Path(value)
    if p.is_file():
        return p.read_text(encoding="utf-8", errors="replace")
    return value


def main() -> int:
    parser = argparse.ArgumentParser(
        description="VesselFramework one-file runtime with defensive Evil Twin challenge mode."
    )
    sub = parser.add_subparsers(dest="command", required=True)

    sub.add_parser("selftest", help="Verify embedded bundle and compile embedded Python files.")
    sub.add_parser("list", help="List all embedded resources.")

    p_extract = sub.add_parser("extract", help="Materialize embedded resources to a directory.")
    p_extract.add_argument("target", nargs="?", default="./vesselframework_extracted")

    p_show = sub.add_parser("show", help="Print an embedded resource.")
    p_show.add_argument("name")

    p_case = sub.add_parser("case", help="Run the embedded deterministic case runner.")
    p_case.add_argument("args", nargs=argparse.REMAINDER)

    p_agent = sub.add_parser("agent", help="Run the embedded VesselFramework agent.")
    p_agent.add_argument("args", nargs=argparse.REMAINDER)

    p_rec = sub.add_parser("recognition", help="Run the Identity & Recognition Provenance Gate on a JSON evidence file.")
    p_rec.add_argument("--subject", required=True)
    p_rec.add_argument("--evidence", required=True, help="Path to JSON list/object containing evidence items.")
    p_rec.add_argument("--json", action="store_true", help="Emit machine-readable JSON.")

    p_twin = sub.add_parser("twin", help="Challenge an existing analysis.")
    p_twin.add_argument("--question", required=True)
    p_twin.add_argument("--draft", required=True, help="Draft text or path to a text/Markdown file.")
    p_twin.add_argument("--evidence", default="", help="Evidence text or path.")
    p_twin.add_argument("--offline", action="store_true")

    p_duel = sub.add_parser("duel", help="Primary analysis -> Evil Twin -> adjudicator.")
    p_duel.add_argument("--question", required=True)
    p_duel.add_argument("--evidence", default="", help="Evidence text or path.")

    args = parser.parse_args()

    if args.command == "selftest":
        return selftest()

    if args.command == "list":
        for name in list_resources():
            print(name)
        return 0

    if args.command == "extract":
        root = materialize(Path(args.target))
        print(root.resolve())
        return 0

    if args.command == "show":
        show_resource(args.name)
        return 0

    if args.command == "case":
        return run_legacy("vesselframework_case_runner.py", args.args)

    if args.command == "agent":
        return run_legacy("vesselframework_agent.py", args.args)

    if args.command == "recognition":
        evidence_text = _read_arg_or_file(args.evidence)
        payload = json.loads(evidence_text)
        if isinstance(payload, dict):
            items = payload.get("evidence", payload.get("items", []))
        else:
            items = payload
        if not isinstance(items, list):
            raise ValueError("Recognition evidence must be a JSON list or an object containing `evidence`/`items`.")
        result = recognition_gate(args.subject, items)
        if args.json:
            print(json.dumps(result, indent=2, ensure_ascii=False))
        else:
            print(recognition_report(result))
        return 0

    if args.command == "twin":
        draft = _read_arg_or_file(args.draft)
        evidence = _read_arg_or_file(args.evidence)
        print(run_twin(args.question, draft, evidence, args.offline))
        return 0

    if args.command == "duel":
        evidence = _read_arg_or_file(args.evidence)
        primary, twin, arbiter = run_duel(args.question, evidence)
        print("\n=== PRIMARY ===\n")
        print(primary)
        print("\n=== EVIL TWIN ===\n")
        print(twin)
        print("\n=== ADJUDICATED RESULT ===\n")
        print(arbiter)
        return 0

    return 2


if __name__ == "__main__":
    raise SystemExit(main())
